for r in p[\"states\"]:
 key=(r.get(\"browser\"),r.get(\"viewport\"),r.get(\"state\"));
 if key in wanted:
  s=r[\"snapshot\"]; cooks=next((m for m in s[\"markers\"] if m.get(\"key\")==\"cooks\"),None); print(json.dumps({\"browser\":key[0],\"viewport\":key[1],\"state\":key[2],\"safe_padding\":s[\"safe_padding\"],\"cooks\":cooks,\"persistent_obstacles\":s[\"persistent_opaque_chrome\"][\"rectangles\"]},separators=(\",\",\":\")))'"

/bin/zsh -lc "rtk python3 -c 'import importlib.util,json; spec=importlib.util.spec_from_file_location(\"qa_map_geometry\",\"scripts/qa_map_geometry.py\"); m=importlib.util.module_from_spec(spec); spec.loader.exec_module(m); p=json.load(open(\"/tmp/chg272-r1-map-geometry.json\"));
